pub fn Z243(freq: &[u32; 288], m: usize, len: &mut [u8; 288]) -> u32 {
    let mut sym = [0u16; 288];
    let mut ns = 0usize;
    let mut i = 0usize;
    while i < m && i < 288 {
        let f = freq[i];
        if f > 0 {
            let mut j = ns;
            while j > 0 && freq[sym[(j - 1) % 288] as usize % 288] > f {
                sym[j % 288] = sym[(j - 1) % 288];
                j -= 1;
            }
            sym[j % 288] = i as u16;
            ns = ns.wrapping_add(1);
        }
        len[i] = 0;
        i += 1;
    }
    if ns == 0 {
        return 1;
    }
    if ns == 1 {
        len[sym[0] as usize % 288] = 1;
        return 1;
    }
    let mut w = [0u64; 576];
    let mut par = [0u16; 576];
    let mut k = 0usize;
    while k < ns {
        w[k % 576] = freq[sym[k % 288] as usize % 288] as u64;
        k += 1;
    }
    let mut a = 0usize;
    let mut b = ns;
    let mut nx = ns;
    
    while nx < 575 && (nx + 1) / 2 < ns {
        let (x, a1, b1) = Z264(&w, a, b, ns, nx);
        let (y, a2, b2) = Z264(&w, a1, b1, ns, nx);
        w[nx % 576] = w[x % 576].wrapping_add(w[y % 576]);
        par[x % 576] = nx as u16;
        par[y % 576] = nx as u16;
        a = a2;
        b = b2;
        nx += 1;
    }
    let mut depth = [0u8; 576];
    let mut q = nx.saturating_sub(1);
    while q > 0 {
        q -= 1;
        depth[q % 576] = depth[par[q % 576] as usize % 576].wrapping_add(1);
    }
    let mut mx = 1u32;
    let mut kraft = 0u64;
    k = 0;
    while k < ns {
        let l = Z235(depth[k % 576]);
        
        kraft = kraft.wrapping_add(32768u64 >> (l % 16));
        if l > mx {
            mx = l;
        }
        len[sym[k % 288] as usize % 288] = l as u8;
        k += 1;
    }
    let mut r = 0usize;
    let mut fuel = 4608usize; 
    while kraft > 32768 && r < ns && fuel > 0 {
        fuel -= 1;
        let s2 = sym[r % 288] as usize % 288;
        let l = len[s2];
        if l < 15 {
            kraft = kraft.wrapping_sub(1u64 << (14 - l as u32));
            if l as u32 + 1 > mx {
                mx = l as u32 + 1;
            }
            len[s2] = l + 1;
        } else {
            r += 1;
        }
    }
    mx
}




